async function authorizeAndExchange(loginToken: string, cId: string, cSecret: string, redirectUri: string) {
	const authRes = await request
		.post(`/oauth/authorize`)
		.type('form')
		.send({
			token: loginToken,
			client_id: cId,
			response_type: 'code',
			redirect_uri: redirectUri,
			state: 'test-state',
			allow: 'yes',
		})
		.expect(302);

	const location = new URL(authRes.headers.location);
	const code = location.searchParams.get('code') as string;

	const tokenRes = await request
		.post(`/oauth/token`)
		.type('form')
		.send({
			grant_type: 'authorization_code',
			code,
			client_id: cId,
			client_secret: cSecret,
			redirect_uri: redirectUri,
		})
		.expect(200);

	return { accessToken: [REDACTED] as string, refreshToken: [REDACTED] as string };
}

