import type { IMessage } from '@rocket.chat/core-typings';
import { parse } from '@rocket.chat/message-parser';
import { render, screen } from '@testing-library/react';
import type { TFunction } from 'i18next';

import { getMarkdownParserLimit } from './getMarkdownParserLimit';
import { normalizeThreadMessage } from './normalizeThreadMessage';
import { filterMarkdown } from '../../lib/markdown/parser/filtered/filtered';

jest.mock('./getMarkdownParserLimit');
jest.mock('../../lib/markdown/parser/filtered/filtered');
jest.mock('@rocket.chat/message-parser');
jest.mock('../../rocketchat.info', () => ({}));

const mockedGetMarkdownParserLimit = jest.mocked(getMarkdownParserLimit);
const mockedFilterMarkdown = jest.mocked(filterMarkdown);
const mockedParse = jest.mocked(parse);

const t = ((key: string) => key) as TFunction;

describe('normalizeThreadMessage', () => {
	beforeEach(() => {
		mockedGetMarkdownParserLimit.mockReturnValue(Infinity);
		mockedFilterMarkdown.mockImplementation((text) => text);
		mockedParse.mockImplementation((text) => [{ type: 'PARAGRAPH', value: [{ type: 'PLAIN_TEXT', value: text }] }] as any);
	});

	afterEach(() => {
		jest.resetAllMocks();
	});

	it('should parse message through filterMarkdown and parse when within limit', () => {
		const message = { msg: 'Hello world', mentions: [], attachments: [] } as unknown as IMessage;
		normalizeThreadMessage(message, t);

		expect(mockedFilterMarkdown).toHaveBeenCalledWith('Hello world');
		expect(mockedParse).toHaveBeenCalledWith('Hello world', { emoticons: true });
	});

	it('should skip filterMarkdown and parse when message exceeds limit', () => {
		mockedGetMarkdownParserLimit.mockReturnValue(5);

		const message = { msg: 'This message is longer than the limit', mentions: [], attachments: [] } as unknown as IMessage;
		const result = normalizeThreadMessage(message, t);

		expect(mockedFilterMarkdown).not.toHaveBeenCalled();
		expect(mockedParse).not.toHaveBeenCalled();

		// Still renders (as plain text AST through Markup)
		expect(result).not.toBeNull();
		const { container } = render(<>{result}</>);
		expect(container.textContent).toContain('This message is longer than the limit');
	});

	it('should render one block per line when the message exceeds the limit', () => {
		mockedGetMarkdownParserLimit.mockReturnValue(5);

		const message = { msg: 'line one\nline two', mentions: [], attachments: [] } as unknown as IMessage;
		const result = normalizeThreadMessage(message, t);

		expect(mockedParse).not.toHaveBeenCalled();

		render(<>{result}</>);

		// `getByText` matches an element whose own text equals the query, so these only pass if each
		// line got its own block. A single text node holding the `\n` would normalize to
		// "line one line two" and neither query would match, which is exactly the collapsed rendering
		// this guards against.
		expect(screen.getByText('line one')).toBeInTheDocument();
		expect(screen.getByText('line two')).toBeInTheDocument();
	});

	it('should return null when msg is empty and no attachments', () => {
		const message = { msg: '', mentions: [], attachments: undefined } as unknown as IMessage;
		expect(normalizeThreadMessage(message, t)).toBeNull();
	});

	it('should return attachment title when msg is empty but attachment has title', () => {
		const message = { msg: '', mentions: [], attachments: [{ title: 'file.pdf' }] } as unknown as IMessage;
		const result = normalizeThreadMessage(message, t);

		const { container } = render(<>{result}</>);
		expect(container.textContent).toBe('file.pdf');
	});

	it('should return attachment description when msg is empty and attachments have no title', () => {
		const message = { msg: '', mentions: [], attachments: [{ description: 'desc' }] } as unknown as IMessage;
		const result = normalizeThreadMessage(message, t);

		const { container } = render(<>{result}</>);
		expect(container.textContent).toBe('desc');
	});

	it('should return null when parse throws an error', () => {
		mockedParse.mockImplementation(() => {
			throw new Error('parse error');
		});

		const message = { msg: 'test', mentions: [], attachments: [] } as unknown as IMessage;
		expect(normalizeThreadMessage(message, t)).toBeNull();
	});

	it('should return the message type text for a removed message without content', () => {
		const message = {
			t: 'rm',
			msg: '',
			editedAt: new Date(),
			editedBy: { _id: 'uid', username: 'user' },
			mentions: [],
			attachments: [],
		} as unknown as IMessage;

		expect(normalizeThreadMessage(message, t)).toBe('Message_removed');
		expect(mockedFilterMarkdown).not.toHaveBeenCalled();
		expect(mockedParse).not.toHaveBeenCalled();
	});

	it('should render the message content when a `t: rm` message still has content', () => {
		const message = { t: 'rm', msg: 'Hello world', mentions: [], attachments: [] } as unknown as IMessage;

		expect(normalizeThreadMessage(message, t)).not.toBe('Message_removed');
		expect(mockedParse).toHaveBeenCalledWith('Hello world', { emoticons: true });
	});
});

# API Development Guidelines

## Creating Automatic OpenAPI Specifications

When developing new endpoints or modifying existing ones, follow these guidelines to ensure automatic OpenAPI specification generation and request/response validation.

### Using Status Codes and AJV Schema

1. **Status Codes**: Ensure that each response from your endpoint includes the appropriate HTTP status code.
2. **AJV Schema Validation**: Use the AJV schema to validate the response structure. This ensures that the response adheres to the defined schema.
3. **Query and Body Parameters**: Use the new `query` and `body` parameters to validate the inputs to your endpoints. This ensures that the incoming request data adheres to the defined schema.

### Steps to Follow

1. **Define the Schema**: Create a schema for your endpoint response using AJV. This schema will be used to validate the response structure.
2. **Optional Input Validation**: Optionally, you can validate your input parameters (query and body) using AJV schemas. This helps ensure that the incoming request data adheres to the defined schema.
3. **Validation in Test Environments**: When an endpoint is created or changed, the response will be validated in TEST environments. If the response does not match the schema, an error will be thrown.

### Deprecation Notice

The `addRoute` method is now deprecated. Instead, use the following methods available inside the API instance:

- `.get`
- `.post`
- `.put`
- `.delete`

These methods provide a more structured and clear approach to defining your API endpoints.

The `validateParams` property is now deprecated. Instead, use the `query` and `body` properties to validate the inputs to your endpoints. This change provides a more structured and clear approach to input validation.

### Example

Here is an example of how to define an endpoint using the new methods and schema validation:

```typescript
import { API } from 'path/to/api';
import Ajv from 'ajv';

const ajv = new Ajv();

API.v1
	.get(
		'endpoint-name',
		{
			authRequired: true,
			query: ajv.compile({
					type: 'object',
					properties: {
						param1: { type: 'string' },
						param2: { type: 'number' },
					},
					required: ['param1'],
			}),
			body: ajv.compile({
					type: 'object',
					properties: {
						field1: { type: 'string' },
						field2: { type: 'boolean' },
					},
					required: ['field1'],
			}),
			response: {
				200: ajv.compile({
					additionalProperties: false,
				    type: 'object',
                    properties: {
						count: {
							type: 'number',
							description: 'The number of sounds returned in this response.',
						},
						offset: {
							type: 'number',
							description: 'The number of sounds that were skipped in this response.',
						},
						total: {
							type: 'number',
							description: 'The total number of sounds that match the query.',
						},
						success: {
							type: 'boolean',
							description: 'Indicates if the request was successful.',
						},
						items: {
							type: 'array',
							items: {
								type: 'object',
								properties: {
								_id: {
									type: 'string',
								},
								prop1: {
									type: 'number',
								},
								prop2: {
									type: 'string',
								},
								prop3: {
									type: 'string',
								},
							},
							required: ['_id', 'prop1', 'prop2', 'prop3'],
							},
						},
					},
				}),
				401: ajv.compile({
					additionalProperties: false,
					type: 'object',
					properties: {
						error: {
							type: 'string',
						},
						status: {
							type: 'string',
							nullable: true,
						},
						message: {
							type: 'string',
							nullable: true,
						},
						success: {
							type: 'boolean',
							description: 'Indicates if the request was successful.',
						},
					},
					required: ['success', 'error'],
				}),
			},
		},

		async function action() {
			const result = await anyLogic();
			return API.v1.success(result);
		},
	)
```

By following these guidelines, you ensure that your API endpoints are well-documented, validated, and maintainable.

import type { IThreadMessage } from '@rocket.chat/core-typings';
import { QueryClient } from '@tanstack/react-query';

import { mutateThreadMessagesInfiniteData, upsertThreadMessageInCache, type ThreadMessagesInfiniteData } from './threadMessageUtils';

const rid = 'room1';
const tmid = 'thread1';
const queryKey = ['rooms', rid, 'threads', tmid, 'messages'] as const;

const createMessage = (id: string, ts: number): IThreadMessage =>
	({
		_id: id,
		rid,
		tmid,
		msg: id,
		ts: new Date(ts).toISOString() as any,
		u: { _id: 'user1', username: 'user1' },
		_updatedAt: new Date(ts).toISOString() as any,
	}) as IThreadMessage;

// A thread with 200 replies, one cached page holding reply-075..reply-124.
const createAnchoredCache = (): ThreadMessagesInfiniteData => ({
	pages: [
		{
			items: Array.from({ length: 50 }, (_, i) => createMessage(`reply-${String(i + 75).padStart(3, '0')}`, i + 75)),
			itemCount: 200,
		},
	],
	pageParams: [75],
});

describe('mutateThreadMessagesInfiniteData', () => {
	let queryClient: QueryClient;

	beforeEach(() => {
		queryClient = new QueryClient();
	});

	it('shifts every stored pageParam forward when a message newer than everything cached is inserted', () => {
		queryClient.setQueryData(queryKey, createAnchoredCache());

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			messages.push(createMessage('reply-200', 1000));
			messages.sort((a, b) => new Date(a.ts).getTime() - new Date(b.ts).getTime());
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pages[0].itemCount).toBe(201);
		expect(data?.pages[0].items.map((m) => m._id)).toContain('reply-200');
		expect(data?.pageParams).toEqual([76]);
	});

	it('keeps a pageParam of 0 unshifted when a newer message is inserted and user is at the newest message', () => {
		const cache: ThreadMessagesInfiniteData = {
			pages: [{ items: [createMessage('reply-150', 150), createMessage('reply-199', 199)], itemCount: 200 }],
			pageParams: [0],
		};
		queryClient.setQueryData(queryKey, cache);

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			messages.push(createMessage('reply-200', 1000));
			messages.sort((a, b) => new Date(a.ts).getTime() - new Date(b.ts).getTime());
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pages[0].itemCount).toBe(201);
		expect(data?.pages[0].items.map((m) => m._id)).toContain('reply-200');
		expect(data?.pageParams).toEqual([0]);
	});

	it('shifts pageParams when the inserted message ties the newest cached timestamp', () => {
		queryClient.setQueryData(queryKey, createAnchoredCache());

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			messages.push(createMessage('reply-200', 124));
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pages[0].itemCount).toBe(201);
		expect(data?.pageParams).toEqual([76]);
	});

	it('shifts every page pageParam, not just the last one, when a newer message arrives', () => {
		const cache: ThreadMessagesInfiniteData = {
			pages: [
				{ items: [createMessage('reply-025', 25), createMessage('reply-026', 26)], itemCount: 200 },
				{ items: [createMessage('reply-075', 75), createMessage('reply-076', 76)], itemCount: 200 },
			],
			pageParams: [25, 75],
		};
		queryClient.setQueryData(queryKey, cache);

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			messages.push(createMessage('reply-200', 1000));
			messages.sort((a, b) => new Date(a.ts).getTime() - new Date(b.ts).getTime());
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pageParams).toEqual([26, 76]);
	});

	it('does not shift pageParams when the inserted message is older than what is already cached', () => {
		queryClient.setQueryData(queryKey, createAnchoredCache());

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			messages.unshift(createMessage('reply-010', 10));
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pages[0].itemCount).toBe(201);
		expect(data?.pageParams).toEqual([75]);
	});

	it('does not shift pageParams when a cached message is deleted', () => {
		queryClient.setQueryData(queryKey, createAnchoredCache());

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			const index = messages.findIndex((m) => m._id === 'reply-100');
			messages.splice(index, 1);
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pages[0].items.map((m) => m._id)).not.toContain('reply-100');
		expect(data?.pages[0].itemCount).toBe(199);
		expect(data?.pageParams).toEqual([75]);
	});

	it('does not shift pageParams when an existing message is edited in place', () => {
		queryClient.setQueryData(queryKey, createAnchoredCache());

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			const index = messages.findIndex((m) => m._id === 'reply-100');
			messages[index] = { ...messages[index], msg: 'edited' };
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pages[0].itemCount).toBe(200);
		expect(data?.pageParams).toEqual([75]);
	});

	it('removes a message from every cached page when its id was duplicated across pages, not just the first occurrence', () => {
		const cache: ThreadMessagesInfiniteData = {
			pages: [
				{ items: [createMessage('reply-058', 58), createMessage('reply-059', 59), createMessage('reply-060', 60)], itemCount: 200 },
				{ items: [createMessage('reply-060', 60), createMessage('reply-061', 61)], itemCount: 200 },
			],
			pageParams: [58, 60],
		};
		queryClient.setQueryData(queryKey, cache);

		mutateThreadMessagesInfiniteData(queryClient, queryKey, (messages) => {
			const index = messages.findIndex((m) => m._id === 'reply-060');
			messages.splice(index, 1);
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);
		const allIds = data?.pages.flatMap((page) => page.items.map((m) => m._id)) ?? [];

		expect(allIds).not.toContain('reply-060');
		expect(data?.pages[0].itemCount).toBe(199);
	});

	it('collapses a duplicated id into a single entry, keeping the most recently updated copy, even when the mutation is a no-op', () => {
		const stale = createMessage('reply-060', 60);
		const fresh: IThreadMessage = { ...createMessage('reply-060', 60), msg: 'edited', _updatedAt: new Date(9999).toISOString() as any };
		const cache: ThreadMessagesInfiniteData = {
			pages: [
				{ items: [stale], itemCount: 200 },
				{ items: [fresh], itemCount: 200 },
			],
			pageParams: [60, 60],
		};
		queryClient.setQueryData(queryKey, cache);

		mutateThreadMessagesInfiniteData(queryClient, queryKey, () => {
			// no-op mutation: only the dedup pass should change the cache
		});

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);
		const allItems = data?.pages.flatMap((page) => page.items) ?? [];

		expect(allItems).toHaveLength(1);
		expect(allItems[0].msg).toBe('edited');
	});
});

describe('upsertThreadMessageInCache', () => {
	let queryClient: QueryClient;

	beforeEach(() => {
		queryClient = new QueryClient();
	});

	it('seeds the cache with pageParams [0] when nothing was cached yet', () => {
		upsertThreadMessageInCache(createMessage('reply-000', 0), rid, tmid, queryClient);

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);

		expect(data?.pages[0].itemCount).toBe(1);
		expect(data?.pageParams).toEqual([0]);
	});

	it('keeps the next-page fetch offset aligned with the real data after a live reply arrives, so no message is skipped', () => {
		queryClient.setQueryData(queryKey, createAnchoredCache());

		upsertThreadMessageInCache(createMessage('reply-200', 1000), rid, tmid, queryClient);

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);
		const [pageParam] = data?.pageParams ?? [];

		expect(data?.pages[0].itemCount).toBe(201);
		// useThreadMessagesQuery's getNextPageParam computes offset = pageParam - count (50),
		// so 76 (not the stale 75) produces offset 26, which includes reply-125.
		expect(pageParam).toBe(76);
	});

	it('updates an existing message in place without shifting pageParams', () => {
		queryClient.setQueryData(queryKey, createAnchoredCache());

		const edited = { ...createMessage('reply-100', 100), msg: 'edited' };
		upsertThreadMessageInCache(edited, rid, tmid, queryClient);

		const data = queryClient.getQueryData<ThreadMessagesInfiniteData>(queryKey);
		const updated = data?.pages[0].items.find((m) => m._id === 'reply-100');

		expect(updated?.msg).toBe('edited');
		expect(data?.pages[0].itemCount).toBe(200);
		expect(data?.pageParams).toEqual([75]);
	});
});

import { afterEach, beforeEach, describe, it } from 'node:test';

import { expect } from 'chai';
import proxyquire from 'proxyquire';
import sinon from 'sinon';

const modelsMock = {
	LivechatContacts: {
		findOneEnabledById: sinon.stub(),
	},
};

const settingsMock = {
	get: sinon.stub(),
};

const { runIsAgentAvailableToTakeContactInquiry } = proxyquire.noCallThru().load('./isAgentAvailableToTakeContactInquiry', {
