	'../../../server/settings': {
		settings: settingsMock,
	},
});

describe('isAgentAvailableToTakeContactInquiry', () => {
	beforeEach(() => {
		modelsMock.LivechatContacts.findOneEnabledById.reset();
		settingsMock.get.reset();
	});

	afterEach(() => {
		sinon.restore();
	});

	it('should return false if the contact is not found', async () => {
		modelsMock.LivechatContacts.findOneEnabledById.resolves(undefined);
		const { value, error } = await runIsAgentAvailableToTakeContactInquiry(() => undefined, 'visitorId', {}, 'rid');

		expect(value).to.be.false;
		expect(error).to.eq('error-invalid-contact');
		expect(
			modelsMock.LivechatContacts.findOneEnabledById.calledOnceWith('contactId', sinon.match({ projection: { unknown: 1, channels: 1 } })),
		);
	});

	it('should return false if the contact is unknown and Livechat_Block_Unknown_Contacts is true', async () => {
		modelsMock.LivechatContacts.findOneEnabledById.resolves({ unknown: true });
		settingsMock.get.withArgs('Livechat_Block_Unknown_Contacts').returns(true);
		const { value, error } = await runIsAgentAvailableToTakeContactInquiry(() => undefined, 'visitorId', {}, 'rid');
		expect(value).to.be.false;
		expect(error).to.eq('error-unknown-contact');
	});

	it('should return false if the contact is not verified and Livechat_Block_Unverified_Contacts is true', async () => {
		modelsMock.LivechatContacts.findOneEnabledById.resolves({
			unknown: false,
			channels: [
				{ verified: false, visitor: { source: { type: 'channelName' }, visitorId: 'visitorId' } },
				{ verified: true, visitor: { source: { type: 'othername' }, visitorId: 'visitorId' } },
			],
		});
		settingsMock.get.withArgs('Livechat_Block_Unknown_Contacts').returns(true);
		settingsMock.get.withArgs('Livechat_Block_Unverified_Contacts').returns(true);
		const { value, error } = await runIsAgentAvailableToTakeContactInquiry(() => undefined, 'visitorId', { type: 'channelName' }, 'rid');
		expect(value).to.be.false;
		expect(error).to.eq('error-unverified-contact');
	});

	it('should return true if the contact has the verified channel', async () => {
		modelsMock.LivechatContacts.findOneEnabledById.resolves({
			unknown: false,
			channels: [
				{ verified: true, visitor: { source: { type: 'channelName' }, visitorId: 'visitorId' } },
				{ verified: false, visitor: { source: { type: 'othername' }, visitorId: 'visitorId' } },
			],
		});
		settingsMock.get.withArgs('Livechat_Block_Unknown_Contacts').returns(true);
		settingsMock.get.withArgs('Livechat_Block_Unverified_Contacts').returns(true);
		const { value } = await runIsAgentAvailableToTakeContactInquiry(() => undefined, 'visitorId', { type: 'channelName' }, 'rid');
		expect(value).to.be.true;
	});

	it('should not look at the unknown field if the setting Livechat_Block_Unknown_Contacts is false', async () => {
		modelsMock.LivechatContacts.findOneEnabledById.resolves({
			unknown: true,
			channels: [
				{ verified: true, visitor: { source: { type: 'channelName' }, visitorId: 'visitorId' } },
				{ verified: false, visitor: { source: { type: 'othername' }, visitorId: 'visitorId' } },
			],
		});
		settingsMock.get.withArgs('Livechat_Block_Unknown_Contacts').returns(false);
		settingsMock.get.withArgs('Livechat_Block_Unverified_Contacts').returns(true);
		const { value } = await runIsAgentAvailableToTakeContactInquiry(() => undefined, 'visitorId', { type: 'channelName' }, 'rid');
		expect(value).to.be.true;
	});

	it('should not look at the verified channels if Livechat_Block_Unverified_Contacts is false', async () => {
		modelsMock.LivechatContacts.findOneEnabledById.resolves({
			unknown: false,
			channels: [
				{ verified: false, visitor: { source: { type: 'channelName' }, visitorId: 'visitorId' } },
				{ verified: false, visitor: { source: { type: 'othername' }, visitorId: 'visitorId' } },
			],
		});
		settingsMock.get.withArgs('Livechat_Block_Unknown_Contacts').returns(true);
		settingsMock.get.withArgs('Livechat_Block_Unverified_Contacts').returns(false);
		const { value } = await runIsAgentAvailableToTakeContactInquiry(() => undefined, 'visitorId', { type: 'channelName' }, 'rid');
		expect(value).to.be.true;
	});

	it('should return true if there is a contact and the settings are false', async () => {
		modelsMock.LivechatContacts.findOneEnabledById.resolves({
			unknown: false,
			channels: [],
		});
		settingsMock.get.withArgs('Livechat_Block_Unknown_Contacts').returns(false);
		settingsMock.get.withArgs('Livechat_Block_Unverified_Contacts').returns(false);
		const { value } = await runIsAgentAvailableToTakeContactInquiry(() => undefined, 'visitorId', { type: 'channelName' }, 'rid');
		expect(value).to.be.true;
	});
});

import { beforeEach, describe, it } from 'node:test';

import { expect } from 'chai';
import proxyquire from 'proxyquire';
import sinon from 'sinon';

const mockUsers = {
	acquireAgentLock: sinon.stub(),
	releaseAgentLock: sinon.stub(),
};

const mockSettings = {
	get: sinon.stub(),
};

const mockHasRoleAsync = sinon.stub();

const { conditionalLockAgent } = proxyquire.noCallThru().load('./conditionalLockAgent', {
	'@rocket.chat/models': { Users: mockUsers },
	'../authorization/hasRole': { hasRoleAsync: mockHasRoleAsync },
	'../../settings': { settings: mockSettings },
});

describe('conditionalLockAgent', () => {
	beforeEach(() => {
		mockUsers.acquireAgentLock.reset();
		mockUsers.releaseAgentLock.reset();
		mockSettings.get.reset();
		mockHasRoleAsync.reset();
	});

	describe('when waiting_queue is enabled', () => {
		beforeEach(() => {
			mockSettings.get.withArgs('Livechat_waiting_queue').returns(true);
			mockHasRoleAsync.resolves(false);
		});

		it('should return acquired: true when lock is successfully acquired', async () => {
			mockUsers.acquireAgentLock.resolves(true);

			const result = await conditionalLockAgent('agent1');

			expect(result.acquired).to.equal(true);
			expect(result.required).to.equal(true);
			expect(mockUsers.acquireAgentLock.calledOnce).to.equal(true);
		});

		it('should return acquired: false when lock is already held by another process', async () => {
			mockUsers.acquireAgentLock.resolves(false);

			const result = await conditionalLockAgent('agent1');

			expect(result.acquired).to.equal(false);
			expect(result.required).to.equal(true);
			expect(mockUsers.acquireAgentLock.calledOnce).to.equal(true);
		});

		it('should call releaseAgentLock when unlock is called', async () => {
			mockUsers.acquireAgentLock.resolves(true);
			mockUsers.releaseAgentLock.resolves(true);

			const result = await conditionalLockAgent('agent1');
			await result.unlock();

			expect(mockUsers.releaseAgentLock.calledOnce).to.equal(true);
			expect(mockUsers.releaseAgentLock.firstCall.args[0]).to.equal('agent1');
			expect(mockUsers.releaseAgentLock.firstCall.args[1]).to.be.instanceOf(Date);
		});

		it('should skip lock acquisition for bot agents', async () => {
			mockHasRoleAsync.resolves(true);

			const result = await conditionalLockAgent('agent1');

			expect(result.acquired).to.equal(false);
			expect(result.required).to.equal(false);
			expect(mockUsers.acquireAgentLock.called).to.equal(false);
		});
	});

	describe('when waiting_queue is disabled', () => {
		beforeEach(() => {
			mockSettings.get.withArgs('Livechat_waiting_queue').returns(false);
		});

		it('should return acquired: false and required: false without calling acquireAgentLock', async () => {
			const result = await conditionalLockAgent('agent1');

			expect(result.acquired).to.equal(false);
			expect(result.required).to.equal(false);
			expect(mockUsers.acquireAgentLock.called).to.equal(false);
			expect(mockHasRoleAsync.called).to.equal(false);
		});

		it('should have a no-op unlock function', async () => {
			const result = await conditionalLockAgent('agent1');
			await result.unlock(); // should not throw an error

			expect(mockUsers.releaseAgentLock.called).to.equal(false);
		});
	});
});

