import type { IRoom } from '@rocket.chat/core-typings';
import { Box, Throbber, Icon } from '@rocket.chat/fuselage';
import { useStableCallback } from '@rocket.chat/fuselage-hooks';
import { MessageComposerAction } from '@rocket.chat/ui-composer';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { AudioRecorder } from '../../../lib/AudioRecorder';
import { useChat } from '../../room/contexts/ChatContext';

const audioRecorder = new AudioRecorder();

export type AudioMessageRecorderProps = {
	rid: IRoom['_id'];
	isMicrophoneDenied?: boolean;
};

const AudioMessageRecorder = ({ rid, isMicrophoneDenied }: AudioMessageRecorderProps) => {
	const { t } = useTranslation();

	const [state, setState] = useState<'loading' | 'recording'>('recording');
	const [time, setTime] = useState('00:00');
	const [recordingInterval, setRecordingInterval] = useState<ReturnType<typeof setInterval> | null>(null);
	const [recordingRoomId, setRecordingRoomId] = useState<IRoom['_id'] | null>(null);

	const stopRecording = useStableCallback(async () => {
		if (recordingInterval) {
			clearInterval(recordingInterval);
		}
		setRecordingInterval(null);
		setRecordingRoomId(null);

		setTime('00:00');

		chat?.action.stop('recording');

		chat?.composer?.setRecordingMode(false);

		const blob = await new Promise<Blob>((resolve) => audioRecorder.stop(resolve));

		return blob;
	});

	const handleUnmount = useStableCallback(async () => {
		if (state === 'recording') {
			await stopRecording();
		}
	});

	const handleRecord = useStableCallback(async () => {
		chat?.composer?.setRecordingMode(true);

		if (recordingRoomId && recordingRoomId !== rid) {
			return;
		}

		try {
			await audioRecorder.start();
			chat?.action.performContinuously('recording');
			const startTime = new Date();
			setRecordingInterval(
				setInterval(() => {
					const now = new Date();
					const distance = (now.getTime() - startTime.getTime()) / 1000;
					const minutes = Math.floor(distance / 60);
					const seconds = Math.floor(distance % 60);
					setTime(`${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`);
				}, 1000),
			);
			setRecordingRoomId(rid);
		} catch (error) {
			console.log(error);
			chat?.composer?.setRecordingMode(false);
		}
	});

	const handleCancelButtonClick = useStableCallback(async () => {
		await stopRecording();
	});

	const chat = useChat();

	const handleDoneButtonClick = useStableCallback(async () => {
		setState('loading');

		const blob = await stopRecording();

		const fileName = `${t('Audio_record')}.mp3`;
		const file = new File([blob], fileName, { type: 'audio/mpeg' });

		await chat?.flows.uploadFiles({ files: [file] });
	});

	useEffect(() => {
		handleRecord();

		return () => {
			handleUnmount();
		};
	}, [handleUnmount, handleRecord]);

	if (isMicrophoneDenied) {
		return null;
	}

	return (
		<Box
			display='flex'
			position='absolute'
			color='default'
			paddingInline={4}
			paddingBlock={12}
			role='group'
			aria-label={t('Audio_recorder')}
		>
			{state === 'recording' && (
				<>
					<MessageComposerAction icon='circle-cross' title={t('Cancel_recording')} onClick={handleCancelButtonClick} />
					<Box display='flex' alignItems='center' marginInline={4} justifyContent='center'>
						<Icon name='rec' color='danger' />
						<Box fontScale='p2' marginInlineStart={4} is='span' minWidth='x40'>
							{time}
						</Box>
					</Box>
					<MessageComposerAction icon='circle-check' title={t('Finish_recording')} onClick={handleDoneButtonClick} />
				</>
			)}
			{state === 'loading' && <Throbber inheritColor size='x12' />}
		</Box>
	);
};

export default AudioMessageRecorder;

import type { IMessage, IRoom } from '@rocket.chat/core-typings';
import { css } from '@rocket.chat/css-in-js';
import { Box, ButtonGroup, Button, Icon, PositionAnimated } from '@rocket.chat/fuselage';
import { useStableCallback } from '@rocket.chat/fuselage-hooks';
import { useTranslation, useToastMessageDispatch } from '@rocket.chat/ui-contexts';
import type { AllHTMLAttributes, RefObject } from 'react';
import { useRef, useEffect, useState } from 'react';

import { UserAction, USER_ACTIVITIES } from '../../../lib/UserAction';
import { VideoRecorder, useVideoRecorderCameraStarted } from '../../../lib/videoRecorder';
import { useChat } from '../../room/contexts/ChatContext';

export type VideoMessageRecorderProps = {
	rid: IRoom['_id'];
	tmid?: IMessage['_id'];
	reference: RefObject<HTMLElement | null>;
} & Omit<AllHTMLAttributes<HTMLDivElement>, 'is'>;

const videoContainerClass = css`
	transform: scaleX(-1);
	filter: FlipH;

	@media (max-width: 500px) {
		& > video {
			width: 100%;
			height: 100%;
		}
	}
`;

const getVideoRecordingExtension = () => {
	const supported = VideoRecorder.getSupportedMimeTypes();
	if (supported.match(/video\/webm/)) {
		return 'webm';
	}
	return 'mp4';
};

const VideoMessageRecorder = ({ rid, tmid, reference }: VideoMessageRecorderProps) => {
	const t = useTranslation();
	const videoRef = useRef<HTMLVideoElement>(null);
	const dispatchToastMessage = useToastMessageDispatch();

	const [time, setTime] = useState<string | undefined>('00:00');
	const [recordingState, setRecordingState] = useState<'idle' | 'loading' | 'recording'>('idle');
	const [recordingInterval, setRecordingInterval] = useState<ReturnType<typeof setInterval> | null>(null);
	const isRecording = recordingState === 'recording';
	const cameraStarted = useVideoRecorderCameraStarted();
	const sendButtonDisabled = !(cameraStarted && !isRecording);

	const chat = useChat();

	const stopVideoRecording = async (rid: IRoom['_id'], tmid?: IMessage['_id']) => {
		if (recordingInterval) {
			clearInterval(recordingInterval);
		}
		setRecordingInterval(null);
		VideoRecorder.stopRecording();
		UserAction.stop(rid, USER_ACTIVITIES.USER_RECORDING, { tmid });
		setRecordingState('idle');
	};

	const handleRecord = async () => {
		if (recordingState === 'recording') {
			stopVideoRecording(rid, tmid);
		} else {
			VideoRecorder.record();
			setRecordingState('recording');
			UserAction.performContinuously(rid, USER_ACTIVITIES.USER_RECORDING, { tmid });
			setTime('00:00');
			const startTime = new Date();
			setRecordingInterval(
				setInterval(() => {
					const now = new Date();
					const distance = (now.getTime() - startTime.getTime()) / 1000;
					const minutes = Math.floor(distance / 60);
					const seconds = Math.floor(distance % 60);
					setTime(`${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`);
				}, 1000),
			);
		}
	};

	const handleSendRecord = async () => {
		const cb = async (blob: Blob) => {
			const fileName = `${t('Video_record')}.${getVideoRecordingExtension()}`;
			const file = new File([blob], fileName, { type: VideoRecorder.getSupportedMimeTypes().split(';')[0] });
			await chat?.flows.uploadFiles({ files: [file] });
		};

		VideoRecorder.stop(cb);
		chat?.composer?.setRecordingVideo(false);
		setTime(undefined);
		stopVideoRecording(rid, tmid);
	};

	const handleCancel = useStableCallback(() => {
		VideoRecorder.stop();
		chat?.composer?.setRecordingVideo(false);
		setTime(undefined);
		stopVideoRecording(rid, tmid);
	});

	useEffect(() => {
		if (!VideoRecorder.getSupportedMimeTypes()) {
			return dispatchToastMessage({ type: 'error', message: t('Browser_does_not_support_recording_video') });
		}

		VideoRecorder.start(videoRef.current ?? undefined, (success) => (!success ? handleCancel() : undefined));

		return () => {
			VideoRecorder.stop();
		};
	}, [dispatchToastMessage, handleCancel, t]);

	return (
		<PositionAnimated visible='visible' anchor={reference} placement='top-end'>
			<Box role='dialog' aria-label={t('Video_record')} backgroundColor='light' padding={4} borderRadius='medium' elevation='2'>
				<Box className={videoContainerClass} overflow='hidden' height={240} borderRadius='medium'>
					<video muted autoPlay playsInline ref={videoRef} width={320} height={240} />
				</Box>
				<Box marginBlockStart={4} display='flex' justifyContent='space-between'>
					<Button aria-label={isRecording ? t('Stop_Recording') : t('Record')} small onClick={handleRecord}>
						<Box is='span' display='flex' alignItems='center' gap={4}>
							<Icon size='x16' name={isRecording ? 'stop-unfilled' : 'rec'} />
							{time && <span>{time}</span>}
						</Box>
					</Button>
					<ButtonGroup>
						<Button small onClick={handleCancel}>
							{t('Cancel')}
						</Button>
						<Button primary small disabled={sendButtonDisabled} onClick={handleSendRecord}>
							{t('Send')}
						</Button>
					</ButtonGroup>
				</Box>
			</Box>
		</PositionAnimated>
	);
};

export default VideoMessageRecorder;

